BEGIN;
SET LOCAL lock_timeout='5s'; SET LOCAL statement_timeout='60s';
LOCK TABLE public.questions IN SHARE ROW EXCLUSIVE MODE;
CREATE TEMP TABLE swsi_before ON COMMIT DROP AS SELECT id, to_jsonb(q) AS row FROM public.questions q;
CREATE TEMP TABLE swsi_batch(id text primary key, status text, note text, url text) ON COMMIT DROP;
INSERT INTO swsi_batch VALUES ('SP-115-2-019','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2026-07-25。本題法規部分為選項D。勞工退休金條例第6條規定雇主應按月提繳退休金，儲存於勞保局設立之勞工退休金個人專戶；第14條規定雇主提繳之退休金不得低於勞工每月工資百分之六；第23條規定月退休金及一次退休金均依勞工個人退休金專戶之本金及累積收益計算，故勞工退休金為確定提撥制，選項D正確；選項B為年金財務理論之錯誤敘述，不涉法規修正。第6條自 2004-06-30 制定公布後未修正，第14條、第23條最近一次修正為 2019-05-15，均早於考試日。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-26 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=N0030020'),('SP105-2-12','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2016-07-23。本題考立法院審議法律案程序。立法院職權行使法第8條第2項規定政府機關提出之議案或立法委員提出之法律案，於院會朗讀標題後即應交付有關委員會審查，但經出席委員提議，二十人以上連署或附議，經表決通過，得逕付二讀，故一讀後不一定交付委員會審查，選項C錯誤；第11條第2項規定第三讀會除發現議案內容有互相牴觸，或與憲法、其他法律相牴觸者外，祇得為文字之修正（選項D）。第8條、第11條自 2007-12-19 修正公布後未再修正（2024-06-24 修正未涉及上開條文）。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-26 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=A0020058'),('SP106-2-14','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2017-07-29。本題考生育給付之制度類型。勞工保險條例第2條規定普通事故保險分生育、傷病、失能、老年及死亡五種給付；國民年金法第2條規定國民年金保險之保險事故分為老年、生育、身心障礙及死亡四種，並給與生育給付。生育給付係由社會保險提供之給付（選項C）。勞工保險條例第2條自 2008-08-13 修正公布後、國民年金法第2條自 2011-06-29 修正公布後均未再修正。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-26 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=N0050001'),('SP107-1-20','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2018-02-03。本題考社會保險之實績費率。考試時勞工保險條例第13條第3項、第4項規定，職業災害保險費率分為行業別災害費率及上、下班災害費率二種，僱用員工達一定人數以上之投保單位，行業別災害費率採實績費率，按其前三年職業災害保險給付總額占應繳職業災害保險費總額之比率每年計算調整（選項C）；同條第2項之普通事故保險費率則依投保薪資一定比率計算，不採實績費率。勞工職業災害保險及保護法自 2022-05-01 施行，依第107條，勞工保險條例第13條第3項至第6項等職業災害保險規定自該法施行之日起不再適用，改依該法第16條：行業別災害費率對僱用員工達一定人數以上之投保單位仍採實績費率，按其最近三年保險給付總額占應繳保險費總額及職業安全衛生之辦理情形每年計算調整。職業災害保險採實績費率之規定未變。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-26 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=N0050031'),('SP107-1-32','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2018-02-03。本題考社會福利公益信託許可及監督辦法第27條：公益信託有違反設立許可條件或監督命令、為有害公益之行為、無正當理由連續三年不為活動等情事之一者，主管機關應通知委託人、信託監察人及受託人於十五日內表示意見；屆期不表示或雖表示而無正當理由者，主管機關得依信託法第77條第1項廢止其許可或為其他必要處置（選項B）。本辦法於 2014-05-05 訂定發布，2017-12-05 僅修正第11條、第30條，第27條未曾修正。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-26 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050192'),('SP110-2-09','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2021-08-21。本題考社團法人與財團法人之成立。民法第30條規定法人非經向主管機關登記，不得成立；第46條規定以公益為目的之社團，於登記前應得主管機關之許可；第59條規定財團於登記前應得主管機關之許可。選項C稱社團法人不需向主管機關登記法人地位，與第30條不符，為錯誤敘述。上開條文自 1982-01-04 修正公布後未再修正。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-26 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=B0000001'),('SP114-1-10','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2025-02-08。本題考我國所得稅之稅式福利。考試時所得稅法第17條（2024-01-03 修正公布）設有扶養親屬免稅額（第1項第1款，選項D）、人身保險保險費列舉扣除額（第1項第2款第2目之2，選項B）及長期照顧特別扣除額（第1項第2款第3目之7，每人每年12萬元，選項A），所得稅法並無工作所得租稅抵減（EITC），故選項C為答案。第17條其後於 2025-12-26、2026-09-11 修正，長期照顧特別扣除額自 2025 年起提高為每人每年18萬元、社會保險之保險費改不受金額限制、未成年受扶養子女之免稅額增加百分之五十；上開三項仍存在，現行所得稅法亦未設工作所得租稅抵減。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-26 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=G0340003'),('SP114-1-17','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2025-02-08。本題考國民年金之性質。國民年金法第1條規定本法係為確保未能於相關社會保險獲得適足保障之國民於老年、生育及發生身心障礙時之基本經濟安全而制定；第2條規定國民年金保險之保險事故分為老年、生育、身心障礙及死亡四種。國民年金係以社會保險方式辦理，選項D稱國民年金不算是社會保險，為錯誤敘述。第1條、第2條自 2011-06-29 修正公布後未再修正（本法最近一次修正為 2020-06-03，僅修正第12條、第40條）。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-26 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050152'),('SW-111-1-01','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2022-02-19。本題考社會工作師法第17條：社會工作師之行為必須遵守社會工作倫理守則之規定；倫理守則由全國社會工作師公會聯合會訂定，提請會員（會員代表）大會通過後，報請中央主管機關備查，故現行守則由中華民國社會工作師公會全國聯合會訂定（選項D）。第17條自 2008-01-16 修正公布全文後未再修正（2023-06-09 修正係增訂第17條之1至第17條之3，未修正本條）。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-26 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050125');
DO $g$ BEGIN
IF (SELECT count(*) FROM swsi_before)<>4800 THEN RAISE EXCEPTION 'count'; END IF;
IF (SELECT count(*) FROM swsi_batch)<>9 THEN RAISE EXCEPTION 'batch size'; END IF;
IF (SELECT count(*) FROM public.questions q JOIN swsi_batch b USING(id) WHERE q.legal_status='unreviewed' AND q.legal_checked_at IS NULL AND q.legal_note IS NULL AND q.legal_source_url IS NULL)<>9 THEN RAISE EXCEPTION 'preimage mismatch'; END IF;
END $g$;
UPDATE public.questions q SET legal_status=b.status, legal_checked_at='2026-11-26T12:00:00+00:00'::timestamptz, legal_note=b.note, legal_source_url=b.url
FROM swsi_batch b WHERE q.id=b.id;
DO $a$ BEGIN
IF (SELECT md5(string_agg(concat_ws(chr(31),q.id,q.legal_status,q.legal_note,q.legal_source_url),chr(30) ORDER BY q.id)) FROM public.questions q JOIN swsi_batch b USING(id) WHERE q.legal_checked_at='2026-11-26T12:00:00+00:00'::timestamptz) IS DISTINCT FROM 'f1f16e1ceba37451f573c7fc7410bdfc' THEN RAISE EXCEPTION 'postimage mismatch'; END IF;
IF (SELECT count(*) FROM public.questions q JOIN swsi_batch b USING(id) WHERE q.legal_checked_at='2026-11-26T12:00:00+00:00'::timestamptz AND q.legal_status=b.status AND q.legal_note=b.note AND q.legal_source_url=b.url)<>9 THEN RAISE EXCEPTION 'postimage count'; END IF;
IF EXISTS (SELECT 1 FROM swsi_before b FULL JOIN public.questions q USING(id) WHERE coalesce(b.id,q.id) NOT IN (SELECT id FROM swsi_batch) AND b.row IS DISTINCT FROM to_jsonb(q)) THEN RAISE EXCEPTION 'unrelated change'; END IF;
IF EXISTS (SELECT 1 FROM swsi_before b JOIN public.questions q USING(id) WHERE b.id IN (SELECT id FROM swsi_batch) AND (b.row - 'legal_status' - 'legal_checked_at' - 'legal_note' - 'legal_source_url') IS DISTINCT FROM (to_jsonb(q) - 'legal_status' - 'legal_checked_at' - 'legal_note' - 'legal_source_url')) THEN RAISE EXCEPTION 'non-legal field changed'; END IF;
END $a$;
SELECT count(*) FILTER (WHERE q.legal_status='verified_current') verified_9, count(*) FILTER (WHERE q.legal_status='changed') changed_0, count(*) total_9 FROM public.questions q JOIN swsi_batch b USING(id);
COMMIT;
